// The bar button (docs\UI_PLAN.md 2): the default key and whether it is on.
inline constexpr const char* kBarKey = "K";

// A row by its spec key (null if none).
inline const Row* FindRow(const char* key)
{
    for (const Tab& t : kTabs)
        for (int s = 0; s < t.count; ++s)
            for (int r = 0; r < t.sections[s].count; ++r)
                if (strcmp(t.sections[s].rows[r].key, key) == 0)
                    return &t.sections[s].rows[r];
    return nullptr;
}

// A row by its bus section and registry key (null if none: an advanced / raw registry row).
inline const Row* FindRegistryRow(const char* section, const char* regKey)
{
    for (const Tab& t : kTabs)
        for (int s = 0; s < t.count; ++s)
            for (int r = 0; r < t.sections[s].count; ++r)
            {
                const Row& row = t.sections[s].rows[r];
                if (row.regKey && strcmp(row.section, section) == 0 && strcmp(row.regKey, regKey) == 0)
                    return &row;
            }
    return nullptr;
}

